// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;

    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(uint256 initialSum, uint256 newSum, address actor) public {
        vm.assume(actor != address(0));

        // Initialize the contract with a first MinSum value.
        vm.prank(actor);
        c.SetMinSum(initialSum);
        vm.prank(actor);
        c.Initialized();

        uint256 frozen = c.MinSum();

        // After initialization, SetMinSum must never change MinSum.
        vm.prank(actor);
        try c.SetMinSum(newSum) { /* reference: guarded, no-op */ } catch { /* alternative observability */ }

        assertTrue(c.MinSum() == frozen);
    }
}
